import Foundation
import simd
import Testing
import ThreeMF
@testable import Claudova

/// Fixtures are generated by Cadova; see `Fixtures/README.md` for their source.
struct ThreeMFMeshLoaderTests {
    private func fixture(_ name: String) throws -> URL {
        let bundle = try #require(Bundle(identifier: "com.mietech.ClaudovaTests"))
        return try #require(bundle.url(forResource: name, withExtension: "3mf", subdirectory: "Fixtures"))
    }

    @Test func loadsSinglePartBox() async throws {
        let model = try await ThreeMFMeshLoader.load(fixture("box"))

        #expect(model.parts.count == 1)
        let part = try #require(model.parts.first)
        #expect(part.semantic == .solid)
        #expect(part.triangleCount == 12)
        #expect(part.positions.count == 36)
        #expect(part.normals.count == 36)
        #expect(part.submeshes.count == 1)
        #expect(part.submeshes.first?.material == nil)
        #expect(model.bounds == ViewerBounds(min: [0, 0, 0], max: [20, 20, 10]))
    }

    @Test func normalsAreUnitLengthAndOutwardForBox() async throws {
        let part = try #require(try await ThreeMFMeshLoader.load(fixture("box")).parts.first)
        let center = part.bounds.center
        for t in stride(from: 0, to: part.positions.count, by: 3) {
            let normal = part.normals[t]
            #expect(abs(simd_length(normal) - 1) < 1e-4)
            let faceCenter = (part.positions[t] + part.positions[t + 1] + part.positions[t + 2]) / 3
            #expect(simd_dot(normal, faceCenter - center) > 0, "triangle \(t / 3) faces inward")
        }
    }

    @Test func loadsPartsSemanticsAndMaterials() async throws {
        let model = try await ThreeMFMeshLoader.load(fixture("multipart"))

        let bySemantic = Dictionary(grouping: model.parts, by: \.semantic)
        #expect(bySemantic[.solid]?.count == 1)
        #expect(bySemantic[.visual]?.count == 1)   // .highlighted()
        #expect(bySemantic[.context]?.count == 1)  // .inBackground()

        // Red box, metallic cylinder, and the highlighted sphere: `.highlighted()` keeps it in the
        // main shape but colors it `.transparent` (alpha 0) so only the red overlay part shows.
        let solid = try #require(bySemantic[.solid]?.first)
        let materials = solid.submeshes.compactMap(\.material)
        #expect(solid.submeshes.count == 3)
        #expect(materials.count == 3)
        #expect(materials.contains { $0.alpha == 0 })

        let red = try #require(materials.first { $0.metallicness == nil && $0.alpha == 1 })
        #expect(red.red > 0.9 && red.green < 0.1 && red.blue < 0.1)

        let metal = try #require(materials.first { $0.metallicness != nil })
        #expect(metal.metallicness == 1)
        #expect(metal.roughness == 0.3)

        // Highlighted geometry is translucent.
        let highlight = try #require(bySemantic[.visual]?.first)
        #expect(highlight.submeshes.contains { ($0.material?.alpha ?? 1) < 1 })
    }

    @Test func boundsCoverOnlySolidParts() async throws {
        let model = try await ThreeMFMeshLoader.load(fixture("multipart"))
        let bounds = try #require(model.bounds)
        // Box 20×10×5 at the origin, a Ø4×8 cylinder centered at x = 30, and the highlighted Ø6
        // sphere at (−10, 0, 3), which stays in the solid part. The Ø4×4 background cube at
        // y = 20…24 must not count. Sphere tessellation means its extremes may be slightly inside.
        #expect(simd_distance(bounds.min, [-13, -3, 0]) < 0.1)
        #expect(simd_distance(bounds.max, [32, 10, 8]) < 0.01)
    }

    @Test func appliesTransformsChildFirst() {
        // Child scales ×2, parent translates +10 in x: (1,0,0) → (2,0,0) → (12,0,0).
        let scale = Matrix3D(values: [[2, 0, 0], [0, 2, 0], [0, 0, 2], [0, 0, 0]])
        let translate = Matrix3D(values: [[1, 0, 0], [0, 1, 0], [0, 0, 1], [10, 0, 0]])
        let result = ThreeMFMeshLoader.transformedVertices(
            [Mesh.Vertex(x: 1, y: 0, z: 0)], by: [translate, scale]
        )
        #expect(result == [SIMD3<Float>(12, 0, 0)])
    }
}

@MainActor
struct FileWatcherTests {
    @Test func reportsAtomicReplacementAndDeletion() async throws {
        let directory = FileManager.default.temporaryDirectory
            .appending(path: "FileWatcherTests-\(UUID().uuidString)", directoryHint: .isDirectory)
        defer { try? FileManager.default.removeItem(at: directory) }
        let file = directory.appending(path: "Models/model.3mf")

        var changes = 0
        let watcher = FileWatcher(url: file, debounce: .milliseconds(20)) { changes += 1 }

        try Data("one".utf8).write(to: file, options: .atomic)
        try await waitUntil { changes == 1 }

        try Data("two!".utf8).write(to: file, options: .atomic)
        try await waitUntil { changes == 2 }

        try FileManager.default.removeItem(at: file)
        try await waitUntil { changes == 3 }
        withExtendedLifetime(watcher) {}
    }

    private func waitUntil(timeout: Duration = .seconds(3), _ condition: () -> Bool) async throws {
        let deadline = ContinuousClock.now + timeout
        while !condition() {
            #expect(ContinuousClock.now < deadline, "timed out")
            if ContinuousClock.now >= deadline { return }
            try await Task.sleep(for: .milliseconds(10))
        }
    }
}

struct ReframingTests {
    private let box = ViewerBounds(min: [0, 0, 0], max: [20, 20, 10])

    @Test func framesFirstModel() {
        #expect(ModelPreview.shouldReframe(from: nil, to: box))
    }

    @Test func keepsCameraForSmallEdits() {
        let slightlyTaller = ViewerBounds(min: [0, 0, 0], max: [20, 20, 14])
        #expect(!ModelPreview.shouldReframe(from: box, to: slightlyTaller))
    }

    @Test func reframesWhenModelGrowsShrinksOrMoves() {
        #expect(ModelPreview.shouldReframe(from: box, to: ViewerBounds(min: [-15, 0, 0], max: [80, 68, 67])))
        #expect(ModelPreview.shouldReframe(from: box, to: ViewerBounds(min: [0, 0, 0], max: [5, 5, 2])))
        #expect(ModelPreview.shouldReframe(from: box, to: ViewerBounds(min: [40, 0, 0], max: [60, 20, 10])))
    }
}
